  "secrets.wall": "RELÉ RACHADO\n Apontar e disparar para a fenda brilhante.",
  "secrets.plates": "SEGREDO · PLACAS DE PRESSÃO\n Passo em 1 → 2 → 3: esquerda, direita, meio.",
  "secrets.runes": "SEGREDO · BATER RUNAS\n Atira à esquerda, à direita, no meio de um sino.\nCubos de ouro marcam a batida, mesmo quando silenciados.",
  "secrets.braziers": "SEGREDO · TRÊS BRAZILS\nAs armas de fogo acendem os brazires.\n Põe-te na almofada de ouro, depois aponta e dispara.",
  "secrets.ice": "SEGREDO · CRUZAMENTO CONGELADO\nCongele o cristal azul e depois atravesse a água.\n Carrega na almofada de ouro e depois dispara.",
