  "secrets.king_intro": "TRÊS COLECCIONADORES. UM REI.",
  "secrets.shadow_intro": "CONHEÇO TODOS OS TEUS MOVIMENTOS.",
  "secrets.golden_name": "Rei Dourado",
  "secrets.shadow_name": "Herói da Sombra",
  "secrets.golden_title": "SEGREDO · O COLECIONADOR DE COLECIONADORES",
  "secrets.shadow_title": "SEGREDO · O TEU REFLEXO LEMBRA-SE",
  "secrets.skin": "Armadura de Relé Pixel",
  "secrets.skin_short": "Relé de Pixels",
  "secrets.skin_condition": "Resolva uma sala secreta ou descubra o antigo código direcional.",
  "secrets.category": "SEGREDO",
  "secrets.lore_name": "O Relay Esquecido",
  "secrets.developer_name": "A Mudança Noturna",
  "secrets.lore": "A equipa de manutenção escondeu uma oficina atrás de uma parede falsa. Três lâmpadas lembram-se da ordem: esquerda, direita, meio. Cada relé resolvido ainda envia um agradecimento.",
  "secrets.developer_lore": "Um pequeno quarto para todos que mantinham as ilhas a funcionar, o robô dança porque alguém finalmente voltou.",
  "secrets.king_lore": "SECRET: Três Goldbugs desaparecidos acordaram seu rei. Sua coroa se lembra de cada moeda roubada. Observe os anéis de aterrissagem dourados. Continue se movendo e cuidado com seu vento-up.",
  "secrets.shadow_lore": "SECRET: Uma noite perfeita deixa um reflexo para trás. Ele circula através de seus padrões de armas; seu poder emprestado tem limites seguros. Continue se movendo e observe seu vento-up.",
  "secrets.a_room": "Fora do Mapa",
