  "content.84fee1b908": "Lâminas de vento cruzado",
  "content.21f48f0714": "Lâminas crescentes emparelhadas cruzam para fora, depois cortam de volta ao longo de um caminho de retorno curvado.",
  "content.bceb0fd05d": "Bobinas Tesla",
  "content.20e9db560e": "Solta bobinas atrás de ti, eles zap próximos inimigos e eletrificar a linha para a bobina anterior.",
  "content.3fa4624af4": "Enxame de mísseis",
  "content.d5a30861d8": "Fãs pequenos mísseis em movimento numa onda cambaleante, pequenas explosões saturam a multidão.",
  "content.33308c454a": "Fragmentos de prisma",
  "content.7b8ce4b3a3": "Cristais ricochete entre inimigos. Cada um se divide em dois cristais menores em seu primeiro golpe.",
  "content.6ae4da1570": "Chicote de luz",
  "content.dda58a2099": "CLIQUE ESTÃO: varrer um feixe flexível através de um arco largo. Cada balanço atinge um inimigo uma vez.",
  "content.d20d4a8f64": "Torre de bolso",
  "content.5191e9018c": "CLIQUE DIREITO: implante um sentinela no cursor. Ele rastreia e dispara inimigos; colocando outro substitui o mais antigo.",
  "content.b2ecb120df": "Gale de vidro",
  "content.1519201745": "FUSION of Crosswind Blades + Prism Shards. Lâminas crescentes explodem em flashes de cristal enquanto dividem os fragmentos ricocheteados através da multidão.",
  "content.1ded80863d": "Grelha de vespas",
  "content.5085777882": "FUSÃO de Bobinas Tesla + Mísseis Swarm. Uma bateria de mísseis elétricos: explosões micro-mísseis saltam relâmpagos através dos inimigos próximos enquanto bobinas guardam seu rastro.",
  "content.7bd71968dd": "Célula Riposte",
  "content.f9fa5592c1": "Slipstream",
  "content.b3b5901935": "Bis",
  "content.55bf66186a": "Capacitor de numerário",
  "content.718a53f70a": "Segunda Mão",
