  "content.dd10e5feed": "Ovação de pé",
  "content.1b913d3b3f": "Vasculhe um feixe flexível através de um arco largo. Cada balanço atinge um inimigo uma vez.",
  "content.a0fe8c20b1": "Instale um sentinela no cursor. Ele rastreia e dispara inimigos; colocando outro substitui o mais antigo.",
  "content.672418ed7d": "Ao aparar: acertos ganham +⟪0⟫ de dano por ⟪1⟫s. Coloque antes dos multiplicadores.",
  "content.9ec4a01350": "Partida perfeita: Orbit and Trail atinge negócio +⟪0⟫% danos para ⟪1⟫s.",
  "content.f6d86f700c": "Use o seu máximo: +⟪0⟫% danos para ⟪1⟫s.",
  "content.3347d5257c": "Ao resgatar o combo: acertos ganham +⟪0⟫ de dano por ⟪1⟫s. Sem ouro extra.",
  "content.73023179eb": "Após um rebobinar termina: +⟪0⟫% de danos para ⟪1⟫s.",
  "content.9f02fc66b3": "Sobreviva ao sair do mecha: +⟪0⟫% de dano por ⟪1⟫s, incluindo a explosão de ejeção.",
  "content.c21d055973": "Abra um baú: uma nova choque ⟪0⟫m causa ⟪1⟫ danos.",
  "content.4796d804bf": "No fogo das suas Botas flamejantes: acertos de Fogo e Rastro causam +⟪0⟫% de dano.",
  "content.1c57742cae": "Dentro de ⟪0⟫m de cobertura: Orbit and Area atinge negócio +⟪1⟫% de danos.",
  "content.b1bbcf2021": "A ⟪0⟫m ou mais: acertos de Gelo e Corrente causam +⟪1⟫% de dano.",
  "content.a58a60981e": "Cada acerto ganha +⟪0⟫ de dano. Vida máxima x⟪1⟫. Coloque antes dos multiplicadores.",
  "content.5e37395e25": "Cada acerto perde ⟪0⟫ de dano, depois é multiplicado por x⟪1⟫. Favorece golpes fortes; a ordem importa.",
  "content.352a455638": "Suas Queimaduras dão aos aliados +⟪0⟫% de chance de crítico contra esse inimigo (limite da equipe +⟪1⟫%).",
  "content.0836247367": "Outros aliados dentro de ⟪0⟫m recarregar todas as armas ⟪1⟫% mais rápido (capa da equipe +⟪2⟫% de velocidade).",
  "content.e76459c2b5": "Um aliado a até ⟪0⟫m apara: você emite uma nova de Choque de ⟪1⟫m que causa ⟪2⟫ de dano. Recarga: ⟪3⟫s.",
  "content.87006ad396": "Compartilha ⟪0⟫% da vida efetivamente recuperada ao eliminar inimigos com cada aliado a até ⟪1⟫m (limite: ⟪2⟫%).",
  "content.5cb95a9e84": "Um aliado a até ⟪0⟫m faz uma esquiva perfeita: você ganha ⟪1⟫s de invulnerabilidade (limite: ⟪2⟫s). Recarga: ⟪3⟫s.",
  "content.07d6955765": "Um aliado a até ⟪0⟫m usa uma suprema: seus acertos causam +⟪1⟫% de dano por ⟪2⟫s.",
  "content.7042a34e52": "Ceifadores de Gale",
