  "content.173f69c5f1": "Um chicote de queima larga (Fogo), +40 graus e 25% danos.",
  "content.74236350d1": "BEAM CHICOTE EVOLUÇÃO",
  "content.bee03eb48f": "Twinlash",
  "content.c3d026a983": "Um segundo chicote varre atrás de ti, ambos inimigos do choque.",
  "content.8847d2f7b5": "Geleira Sentry",
  "content.c1de1b50b7": "Parafusos de geada larga perfuram 2 inimigos. +20% de danos.",
