  "text.fire_hits_set_enemies_alight_damage_over_3_secon_4b5c8c": "Ataques de fogo incendiam os inimigos: danos durante 3 segundos.",
  "text.shock_6d94cc": "Choque",
  "text.shock_hits_make_an_enemy_take_20_damage_for_2_se_1b0221": "Os golpes de choque fazem um inimigo levar +20% de danos por 2 segundos.",
  "text.freeze_654670": "Congelamento",
  "text.frost_can_freeze_enemies_in_place_frozen_enemies_235019": "O Frost pode congelar inimigos no lugar. Inimigos congelados param de se mover e atacar.",
  "text.exposed_a54eec": "Exposto",
  "text.right_click_status_27d54e": "ESTADO DO CLIQUE DIREITO",
  "text.every_right_click_hit_exposes_the_enemy_30_damag_d8136a": "Cada clique direito mostra o inimigo: +30% de danos de todos por 4 segundos.",
  "text.overload_9f476f": "Sobrecarga",
  "text.combo_burn_shock_4d6d6f": "COMBO: QUEIMADURA + CHOQUE",
  "text.burn_and_shock_on_the_same_enemy_explode_in_an_o_a57fb9": "Queima e Choque no mesmo inimigo explodir em uma explosão de sobrecarga que cresce com o seu nível.",
  "text.shatter_6e8e3e": "Estilhaçamento",
  "text.combo_kill_a_frozen_enemy_5ee0fa": "COMBO: MATAR UM INIMIGO CONGELADO",
  "text.a_frozen_enemy_that_dies_bursts_into_ice_shards__a04a90": "Um inimigo congelado que morre explode em fragmentos de gelo que atingem tudo o que está por perto.",
  "text.napalm_ac4b31": "Napalm",
  "text.combo_blast_a_burning_enemy_bd5453": "COMBO: EXPLODIR UM INIMIGO EM CHAMAS",
  "text.an_explosion_that_catches_a_burning_enemy_spread_2f28fe": "Uma explosão que apanha um inimigo em chamas espalha fogo para tudo na explosão.",
  "text.item_max_lv_456b18": "ITEM · NV MÁX. ⟪0⟫",
  "text.co_op_item_d47243": "PONTO DE COOPERAÇÃO",
  "text.mod_c5a28f": "MOD",
  "text.mod_copies_the_next_slot_27924c": "MOD · COPIA O PRÓXIMO ESPAÇO",
  "text.cursed_mod_146292": "MOD AMALDIÇOADO",
  "text.relic_62a15e": "RELÍQUIA",
  "text.evolution_57341e": "⟪0⟫ EVOLUÇÃO",
  "text.max_a05aea": "MAX ⟪0⟫ + ⟪1⟫",
  "text.follow_the_moving_dirt_mound_only_explosions_rea_d78566": "Siga o monte de terra em movimento, só as explosões chegam ao subsolo, sai do anel vermelho e castiga-o acima do solo.",
  "text.an_armoured_dirt_digger_explosions_still_reach_i_24d97e": "Um Digger de Dirt blindado. Explosões ainda alcançam-no no subsolo; espere fora do anel por sua janela de punição.",
  "text.an_armoured_mirror_bot_with_the_same_readable_sc_a10396": "Um Bot espelho blindado com a mesma varredura legível. Quebre seu ataque de cópia para reivindicar as moedas de bônus.",
  "text.a_big_digger_with_a_wider_eruption_its_longer_ri_f0ce60": "Um grande escavador com uma erupção maior. Seu aviso anel mais longo dá-lhe tempo para se mover; explosivos bater através da sujeira.",
  "text.scans_your_left_click_weapon_then_copies_a_weake_09264c": "Escaneia sua arma de clique esquerdo, em seguida, copia uma versão roxa mais fraca. Mate-o enquanto ele copia moedas de bônus.",
  "text.copies_for_longer_and_keeps_farther_away_the_sca_eea86f": "Copia por mais tempo e mantém-se longe. A linha de varredura trava antes de seu ataque; mova-se de lado.",
  "text.screeches_before_a_wall_of_swarmers_splits_the_a_5886e0": "Escorrega diante de uma parede de enxames que divide a arena. Cortar um espaço, quebrar os ovos verdes antes de eclodir, e persegui-la um retiro.",
  "text.a_fragile_cluster_that_hatches_four_swarmers_aft_adbb89": "Um aglomerado frágil que eclode quatro enxames depois de seis segundos!",
  "text.holds_the_queen_s_wall_for_twelve_seconds_then_j_2f703d": "Segura a parede da Rainha por doze segundos, em seguida, junta-se à perseguição. Dispare uma lacuna através da linha.",
  "text.comes_in_clouds_and_rings_keep_moving_and_let_ar_696216": "Vem em nuvens e anéis. Continue se movendo e deixe as armas área fazer o trabalho.",
  "text.flashes_red_then_lunges_sidestep_the_lunge_and_i_ff7780": "Flashes vermelho, depois pulmãos. Passo de lado o pulmão e está aberto.",
  "text.fast_and_fragile_pierce_and_chain_weapons_clean__db8a3b": "Rápido e frágil, Pierce e as armas acorrentadas limpam os pacotes.",
  "text.keeps_its_distance_and_fires_a_fan_strafe_across_fcd7c5": "Mantém a sua distância e dispara um ventilador. Espalhe através do ventilador, não longe dele.",
  "text.spins_out_a_double_spiral_walk_with_the_gaps_as__21410b": "Roda uma espiral dupla. Caminhe com as lacunas à medida que elas se transformam.",
  "text.three_quick_fans_in_a_row_dash_through_after_the_d70eb7": "Três fãs rápidos seguidos.",
  "text.its_red_line_shows_the_shot_step_off_the_line_be_b5eac6": "A linha vermelha mostra o tiro, sai da linha antes que feche.",
  "text.lines_up_a_charge_you_can_see_on_the_ground_step_9fb66f": "Alinhe-se uma carga que você pode ver no chão. Afaste-se, então punir.",
  "text.big_slow_and_tough_kite_it_while_you_deal_with_t_81c8c9": "Grande, lento e duro, bate-lhe enquanto lidas com o resto.",
  "text.its_fuse_ticks_faster_before_it_blows_back_off_o_69aede": "O fusível bate mais rápido antes de explodir.",
  "text.splits_into_jellets_when_it_pops_area_damage_han_4e2406": "Divide-se em gelatinas quando aparece. Os danos na área tratam das sobras.",
  "text.small_jelly_pieces_weak_on_their_own_ea1dfc": "Pequenos pedaços de gelatina. Fraco por conta própria.",
  "text.its_shield_soaks_hits_from_the_front_and_covers__241479": "Seu escudo absorve golpes da frente e cobre quem se esconde atrás dele. Ele gira lentamente: dar a volta ao lado.",
  "text.hangs_back_and_heals_everything_near_it_in_a_gre_b5a071": "Fica para trás e cura tudo o que está perto com um pulso verde.",
  "text.crouches_then_hops_over_cover_onto_the_ring_it_m_8be58e": "Crouches, depois salta sobre a cobertura para o anel que marca.",
  "text.lobs_shells_from_far_away_each_one_marks_a_red_c_0eed8b": "Cada um marca um círculo vermelho antes de aterrar.",
  "text.rare_and_shiny_runs_away_and_vanishes_after_a_fe_ee55d0": "Raro e brilhante. Foge e desaparece depois de alguns segundos. Pegue-o para um jackpot!",
  "text.a_pylon_that_keeps_hatching_swarmers_take_it_out_a463e8": "Um pilão que continua a chocar os Swarmers.",
  "text.rings_of_bullets_summons_and_a_jump_slam_you_can_d79675": "Anéis de balas, convocações e uma batida de salto que você pode ver chegando.",
  "text.charges_three_times_in_a_row_then_spirals_watch__97dd83": "Cargas três vezes seguidas, depois espirais, cuidado com as linhas de carga.",
  "text.flies_at_range_fires_fans_and_marks_ground_strik_849266": "Voa ao alcance, dispara ventoinhas e marca greves no solo.",
  "text.circles_you_then_dives_along_the_orange_line_and_61bb99": "Circula você, em seguida, mergulha ao longo da linha laranja, e seus amigos seguem em uma coluna. Saia da linha.",
  "text.swims_under_the_sand_where_nothing_can_hit_it_wa_9f4658": "Nada sob a areia onde nada pode atingi-lo: cuidado com a barbatana. Ele explode para fora do anel vermelho, em seguida, fica exposto.",
  "text.rolls_in_wide_arcs_and_grows_as_it_rolls_it_can__5fcd18": "Rola em arcos largos e cresce à medida que rola. Mal pode girar, por isso passo ao lado; grandes quebram em paredes e em você.",
  "text.leaves_burning_puddles_behind_it_and_swells_up_t_07f5e8": "Deixa poças queimando atrás dele e incha até derramar um grande. Mate-o antes que pinte o chão.",
  "text.rewinds_its_path_lights_up_then_marches_straight_fa5ceb": "Rebobina (seu caminho se ilumina), em seguida, marcha em linha reta com o seu esquadrão. Enroscar-se, ele leva danos adicionais.",
  "text.keeps_its_distance_and_blows_a_cone_of_wind_that_1d3a90": "Mantém a sua distância e sopra um cone de vento que o empurra ao redor. Saia do cone pálido ou atravesse.",
