  "text.meltdown_6f4c45": "DERRETER",
  "text.hive_queen_nightshade_64566b": "Rainha da Colmeia: Sombra noturna",
  "text.the_swarm_remembers_da1bcf": "O ENXAME LEMBRA-SE",
  "text.nightshade_walls_and_hives_together_23fb15": "SOMBRA NOTURNA: PAREDES E COLMEIAS JUNTAS",
  "text.the_last_brood_d6aa69": "A ÚLTIMA NINHADA",
  "text.titan_goliath_5e28c8": "Titã Golias",
  "text.the_mountain_that_woke_up_83ba91": "A MONTANHA QUE ACORDOU",
  "text.titan_armour_plate_8de89e": "Placa de Armadura Titan",
  "text.titan_hand_core_7b1c24": "Núcleo da Mão Titan",
  "text.titan_eye_08de1f": "Olho de Titã",
  "text.once_tiny_garden_helpers_these_machines_now_mist_1558e4": "Uma vez pequenos ajudantes de jardim, estas máquinas agora confundem cada bota com uma erva daninha.",
  "text.the_islands_oldest_delivery_bot_still_insists_th_70852e": "O bot de entrega mais antigo das ilhas ainda insiste que cada encomenda chegue pessoalmente.",
  "text.a_courier_with_no_address_left_to_deliver_to_its_14143a": "Um mensageiro sem endereço para entregar. Sua rota termina onde quer que você esteja de pé.",
  "text.a_retired_fireworks_launcher_still_rehearsing_fo_c984e2": "Um lançador de fogos de artifício aposentado, ainda ensaiando para um festival que nunca veio.",
  "text.its_compass_broke_years_ago_it_has_been_checking_adba8f": "A bússola partiu-se há anos, desde então tem verificado todas as direcções.",
  "text.three_short_knocks_were_once_the_repair_crew_s_s_bcacff": "Três batidas curtas já foram a saudação secreta da equipa de reparação.",
  "text.the_watchtower_sentry_can_count_the_scratches_on_c73dcc": "A sentinela da torre de vigia pode contar os arranhões no capacete do outro lado da ilha.",
  "text.a_quarry_hauler_with_excellent_acceleration_and__1029b6": "Um transportador de pedreira com excelente aceleração e absolutamente sem freios.",
  "text.under_that_heavy_shell_is_a_remarkably_small_bat_5d4742": "Sob essa casca pesada está uma bateria notavelmente pequena e um enorme senso de dever.",
  "text.the_warning_sticker_fell_off_the_warning_noise_f_02ac0e": "O autocolante caiu, o ruído de aviso, felizmente, ainda funciona.",
  "text.the_recycling_plant_called_this_self_repair_the__92b56d": "A fábrica de reciclagem chamou-lhe auto-reparação, a equipa chama-lhe papelada extra.",
  "text.a_little_piece_of_a_much_bigger_problem_determin_9984a9": "Um pequeno pedaço de um problema muito maior, determinado a fazer seu próprio caminho.",
  "text.the_factory_foreman_never_received_the_shutdown__614054": "O capataz da fábrica nunca recebeu a ordem de encerramento.",
  "text.built_to_shelter_workers_from_falling_rock_it_st_30a8cc": "Construído para proteger os trabalhadores de cair rocha; ainda coloca todos os outros em primeiro lugar.",
  "text.its_medical_license_expired_with_the_old_network_4e514c": "Sua licença médica expirou com a antiga rede. Sua maneira de dormir permanece entusiástica.",
  "text.the_island_drains_needed_a_maintenance_robot_tha_25ca9a": "Os drenos da ilha precisavam de um robô de manutenção que pudesse saltar.",
  "text.an_irrigation_system_that_found_the_wrong_kind_o_7b0a51": "Um sistema de irrigação que encontrou o tipo errado de recipiente no barracão de abastecimento.",
  "text.every_loose_bolt_on_the_islands_eventually_ends__83950b": "Cada Bolt solto nas ilhas eventualmente acaba nos bolsos deste colecionador.",
  "text.the_first_bopper_promoted_itself_when_the_human__947489": "O primeiro Bopper promoveu-se quando os supervisores humanos partiram. Sua coroa é uma antena.",
  "text.the_excavation_project_stopped_at_bedrock_rex_to_8bf630": "O projecto de escavação parou na base, o Rex levou para o lado pessoal.",
  "text.from_her_aerial_command_post_she_conducts_the_fa_f2d7d4": "De seu posto de comando aéreo, ela conduz o enxame de fábrica como uma banda de bronze.",
  "text.the_central_relay_has_waited_through_a_thousand__3619a8": "O retransmissor central esperou por milhares de pôr-do-sol silenciosos.",
  "text.a_junior_supervisor_practising_a_royal_entrance__43e53e": "Um supervisor júnior que praticava uma entrada real antes da verdadeira promoção.",
  "text.a_prototype_digger_that_already_dreams_of_moving_bf3a30": "Um protótipo escavador que já sonha em mover montanhas.",
  "text.her_first_command_assignment_is_this_island_she__03b2ed": "A sua primeira missão de comando é esta ilha e pretende causar uma boa impressão.",
  "text.a_portable_workshop_unfortunately_its_only_repai_004521": "Uma oficina portátil. Infelizmente, seu único plano de reparo é criar mais problemas.",
  "text.the_network_sends_this_collector_when_an_overdue_f55499": "A rede envia este colecionador quando uma ordem de trabalho atrasada se torna uma lenda.",
  "text.the_newest_member_of_the_recovery_crew_brought_a_cc8b08": "O mais novo membro da equipe de recuperação trouxe um capacete emprestado e um mapa desenhado em lápis de cor. Ambos provaram surpreendentemente confiável.",
  "text.a_rescue_worker_who_once_held_a_collapsing_bridg_44755c": "A armadura pesada é principalmente para a paz de espírito de todos os outros.",
  "text.the_old_island_racing_champion_traded_prize_mone_a07a46": "O velho campeão de corridas da ilha trocou o dinheiro do prémio por um par de botas experimentais. As marcas de queimadura são agora uma assinatura registada.",
  "text.a_radio_operator_who_can_hear_the_rhythm_hiding__b613cb": "Um operador de rádio que consegue ouvir o ritmo a esconder-se em conversas de máquina. Cada tiro é cronometrado para a próxima batida.",
  "text.enemy_92b09d": "INIMIGO",
  "text.a_veteran_of_the_old_island_network_patched_up_a_9525a3": "Um veterano da velha rede da ilha, remendou e enviou de volta em patrulha.",
  "text.keep_moving_and_watch_its_wind_up_e55101": "Continuem a andar e vejam o que acontece.",
  "text.biome_05c008": "BIOMA",
  "text.the_repair_crews_left_flowers_growing_between_th_c2ad6c": "As equipes de reparação deixaram flores crescendo entre as placas de circuito. Cada aventura começa em algum lugar brilhante.",
  "text.buried_relay_towers_still_hum_beneath_the_sunset_9473fb": "Torres de retransmissão enterradas ainda murmuram sob a areia do pôr-do-sol. O vento lembra-se da sua canção.",
  "text.the_mountain_antennae_catch_signals_from_stars_n_ca0ea0": "As antenas da montanha captam sinais de estrelas que ninguém nomeou. O gelo preserva as máquinas antigas.",
  "text.deep_under_the_islands_the_planet_keeps_its_own__c22366": "No fundo das ilhas, o planeta mantém a sua própria fornalha a funcionar. As máquinas aqui aprendiam a amar o calor.",
  "text.another_island_on_the_old_relay_route_waiting_to_cc8d43": "Outra ilha na antiga rota de revezamento, à espera de ser redescoberta.",
  "text.relay_gold_armour_308d74": "Retransmissão de armadura de ouro",
