  "text.frozen_saw_blades_freeze_what_they_slice_shatter_1eb42a": "Lâminas de serra congeladas congelam o que cortam; quebrando as novas ainda pulsam em torno de você.",
  "text.supernova_field_f4b2cc": "Campo Supernova",
  "text.a_blazing_storm_field_its_novas_freeze_shock_and_0c32c6": "Um campo de tempestade em chamas. Suas novas congelar, Chocar e explodir inimigos congelados em pequenas explosões.",
  "text.tesla_traps_c80060": "Armadilhas de Tesla",
  "text.mines_that_burst_into_chain_lightning_jumping_th_963fb4": "Minas que irromperam em correntes relâmpagos, saltando através da multidão ao redor de cada explosão.",
