  "text.rainbow_satellites_orbit_you_flashing_light_burs_ca2017": "Satélites arco-íris orbitam-te, luz piscando explode em hit, enquanto quatro feixes de prisma giram um círculo completo.",
  "text.dragon_cannon_7ad214": "Canhão Dragão",
  "text.a_turret_that_breathes_18_piercing_fireballs_at__290063": "Uma torre que respira 18 bolas de fogo piercing na multidão, e uma trilha em chamas atrás de você.",
