  "text.bouncing_comets_explode_on_every_ricochet_and_6__d30f4a": "Cometas saltitantes explodem em cada ricochete, e 6 estrelas chovem sobre as multidões.",
  "text.meteor_barrage_db8aa0": "Barragem de meteoros",
  "text.burning_meteor_rockets_with_bigger_blasts_that_s_7fc540": "Foguetes de meteoros em chamas com explosões maiores que incendiaram a multidão, mais uma queda de estrelas mais pesada.",
  "text.volt_ricochet_c8ce40": "Ricochete voltaico",
  "text.electric_drones_bounce_2_more_times_and_arc_ligh_8347e5": "drones elétricos saltar mais 2 vezes e arco relâmpago de cada inimigo que eles bater.",
