  "text.enemy_shots_travel_twice_as_fast_8e413e": "Os tiros inimigos viajam duas vezes mais depressa.",
  "text.level_up_5b0ee6": "SUBIU DE NÍVEL!",
  "text.pick_1_of_3_cards_click_or_keys_1_3_the_ribbon_a_c71357": "Escolha 1 de 3 cartas (clique, ou chaves 1-3). A fita na parte inferior diz o que ele atualiza: CLIQUE ESQUECIDO, CLIQUE DIRETO, ESPECIAL, ARMA AUTO ou ITEM.",
  "text.evolution_fork_634218": "ESCOLHA SUA EVOLUÇÃO",
  "text.enough_ranks_to_evolve_pick_one_of_the_two_forms_2fd106": "O suficiente para evoluir! Escolha um dos dois formulários. Cada um muda como o item funciona e adiciona uma tag que o novo Mods pode desligar.",
  "text.the_shop_37cbe7": "A LOJA",
  "text.mods_sit_in_5_slots_and_change_how_your_damage_w_71e69c": "Mods sentar-se em 5 slots e mudar como seus danos funcionam. Ouro que você mantém ganha juros em cada estágio claro, para economizar pode pagar.",
  "text.mod_order_matters_7598df": "A ORDEM DOS MODS IMPORTA",
  "text.damage_flows_through_your_mods_left_to_right_dam_1e221f": "O dano passa pelos Mods da ESQUERDA para a DIREITA: (dano + somas) x multiplicadores. Use as setas para colocar Mods de \"+dano\" antes dos de \"x dano\". Eco copia o Mod à direita.",
  "text.elite_07576c": "ELITE!",
  "text.a_big_tough_enemy_with_a_modifier_shield_fast_sp_891aa6": "Um grande e duro inimigo com um modificador (escudo, rápido, rachando...). Sua barra de crânio mostra sua vida. Bata-o por um baú de tesouro.",
  "text.exposed_e6c328": "EXPOSTO",
  "text.right_click_hits_expose_enemies_30_damage_from_e_38bc87": "Botão direito do mouse bate Expor inimigos: +30% de danos de todos para 4 s. Abra com o botão direito, termine com a esquerda.",
  "text.burn_ticks_damage_shock_makes_enemies_take_20_fr_22dfd5": "Queimar carrapatos danos, Choque faz inimigos tomar +20%, Freeze pára-los. Coloque dois no mesmo inimigo para uma combinação.",
  "text.status_combo_f68922": "COMBINAÇÃO DE ESTADO!",
  "text.burn_shock_overload_blast_kill_a_frozen_enemy_sh_c6ed94": "Queima + Choque = Explosão OVERLOAD. Matar um inimigo congelado = SHATTER. Uma explosão em um inimigo em chamas = NAPALM. Mods pode tornar cada um mais forte.",
  "text.it_changes_its_attacks_at_66_and_33_life_red_zon_bf37e5": "Ele muda os ataques com 66% e 33% de vida. Áreas e linhas vermelhas avisam do perigo: esquive através delas (⟪0⟫) ou apare os tiros (⟪1⟫).",
  "text.treasure_chest_81663c": "BAÚ DO TESOURO",
  "text.walk_into_it_for_a_free_item_on_the_spot_the_arr_3230d7": "Entre nele para um item livre no local. A seta na borda da tela aponta para a mais próxima.",
  "text.special_ready_f6a478": "PREPARADO ESPECIAL",
  "text.press_or_middle_click_for_your_special_it_rechar_03aa5b": "Pressione ⟪0⟫ (ou clique do meio) para o seu especial. Ele recarrega ao longo do tempo.",
  "text.ultimate_ready_d08f2b": "ULTIMATE PRONTO",
  "text.press_perfect_dodges_parries_and_kills_charge_yo_916d6b": "Pressione ⟪0⟫! Perfeito esquiva, parries e mata cobrar o final do seu herói.",
  "text.style_meter_8e60e9": "MEDIDOR DE ESTILO",
  "text.fast_kills_perfect_dodges_and_parries_raise_your_9b344a": "Matas rápidas, perfeitas esquiva e parries elevar o seu estilo de D para SS. Estilo mais elevado dá mais pontuação e XP. Obtendo hit deixa cair.",
  "text.gear_f7f969": "ENGRENAGEM",
  "text.each_gear_rerolls_one_set_of_level_up_cards_on_t_5e783d": "Cada engrenagem troca um conjunto de cartas de nível (⟪0⟫ na tela de subida de nível).",
  "text.stage_clear_4e29fa": "FASE CONCLUÍDA",
  "text.walk_into_the_portal_for_the_next_stage_every_st_adf1cd": "Entre no portal para ir à próxima fase. Cada fase fica mais difícil, e a cada 4 fases você enfrenta o chefe final.",
  "text.a_teammate_revives_you_by_standing_next_to_you_f_b91da8": "Um companheiro de equipe revive você por ficar ao seu lado por 3 s. Clique para assistir outro companheiro de equipe enquanto isso.",
  "text.teammate_down_47afc6": "ALIADO CAÍDO",
  "text.stand_next_to_them_for_3_s_to_revive_them_you_bo_80d4d7": "Fique ao lado deles por 3 s para reanimá-los. Ambos têm um momento de invencibilidade.",
  "text.walk_around_with_or_the_left_stick_you_always_fa_4087eb": "Mova-se com ⟪0⟫ ⟪1⟫ ⟪2⟫ ⟪3⟫ ou o analógico esquerdo. Você sempre olha na direção da mira.",
  "text.aim_and_fire_e2180c": "APONTAR E DISPARAR",
  "text.aim_with_the_mouse_or_right_stick_and_hold_left__395851": "Mire com o mouse ou o analógico direito e segure o CLIQUE ESQUERDO para disparar ⟪0⟫. Destrua os ⟪1⟫ robôs-alvo.",
  "text.hold_right_click_or_x_for_your_its_hits_expose_e_c35ec0": "Segure o CLIQUE DIREITO (ou X) para usar ⟪0⟫. Os acertos deixam os inimigos EXPOSTOS: +30% de dano de todos por 4 s. Exponha o robô grande.",
  "text.press_to_dash_you_can_t_be_hit_mid_dash_dash_thr_ff9c38": "Pressione ⟪0⟫ para traço: você não pode ser atingido no meio do disco. Dash através de um tiro rosa pouco antes de bater em você.",
  "text.press_or_b_right_as_a_pink_shot_reaches_you_to_p_99aaf3": "Pressione ⟪0⟫ (ou B) direito como um tiro rosa atinge você para PARRY-lo de volta para o atirador.",
  "text.your_special_is_ready_press_or_rb_to_set_off_you_fa2e3b": "O seu especial está pronto: pressione ⟪0⟫ (ou RB) para activar o seu ⟪1⟫ ao lado dos bots. Ele recarrega ao longo do tempo.",
  "text.ultimate_df1d2d": "SUPREMA",
  "text.perfect_dodges_parries_and_kills_charge_your_her_5caa68": "Perfeitos esquiva, parries e mata carregar o ULTIMATE do seu herói. Está cheio: pressione ⟪0⟫ (ou R3).",
  "text.level_up_529820": "AUMENTAR O NÍVEL",
  "text.kills_drop_xp_gems_that_fly_to_you_a_full_xp_bar_8d848d": "Kills drop XP gemas que voam para você. Uma barra XP completa é um nível-up: escolha uma das 3 cartas. A fita diz o que ele atualiza.",
  "text.chests_pop_up_on_the_map_every_30_s_the_arrow_at_2bf388": "Os peitos aparecem no mapa a cada 30 s (a seta na borda da tela aponta para eles). Caminhe para este para um item gratuito.",
